function F.nextTool()
    local sel = val("u_toollist", nil)
    local bestOwnedCost = 0
    for _, it in ipairs(F.BUY) do if M.a("Has_" .. it[1]) == true then bestOwnedCost = math.max(bestOwnedCost, it[2]) end end
    for _, it in ipairs(F.BUY) do
        local t = it[1]
        local want = type(sel) ~= "table" or sel[t] == true
        local here = not F.STAND[t] or F.standHere(t)
        if want and here and M.a("Has_" .. t) ~= true and it[2] > bestOwnedCost then
            return t, F.price(t, it[2])
        end
    end
end
function F.bagCost()
    local lv = M.n("BagLevel")
    local c
    pcall(function() c = D.Econ.BagCosts[lv + 1] end)
    if M.a("TutorialFreeBag") == true then return 0 end
    return tonumber(c)
end
function F.plan()
    local steps = {}
    if on("u_bins") then
        for _, b in ipairs(F.binList()) do
            if M.a("BinOpen_" .. b.name) ~= true and b.cost > 0 and (F.binLocked[b.name] or 0) < os.clock() then
                steps[#steps + 1] = { label = b.name .. " bin ($" .. b.price .. "/bug)", cost = b.cost, key = "bin" .. b.name, pay = { kind = "Bin", bin = b.name }, skipIfPoor = true, bin = b.name }
            end
        end
    end
    local maxBag = 8
    pcall(function() maxBag = #D.Econ.BagCapacity - 1 end)
    local bagC = F.bagCost()
    local canBag = on("u_bag") and M.n("BagLevel") < maxBag and M.n("BagCapacity") >= 0 and bagC ~= nil
    if canBag and (M.n("BagLevel") < 5 or bagC == 0) then
        steps[#steps + 1] = { label = "Bag level " .. (M.n("BagLevel") + 1), cost = bagC, key = "bag", pay = { kind = "Bag" } }
    end
    if on("u_stats") and (M.a("Equipped") or "Hands") == "Hands" and M.n("Lvl_Hands_TwoHands") < 1 then
        steps[#steps + 1] = { label = "Two Hands", cost = 100, key = "sHandsTwoHands", pay = { kind = "Upgrade", tool = "Hands", stat = "TwoHands" } }
    end
    if on("u_tools") then
        local t, price = F.nextTool()
        if t then steps[#steps + 1] = { label = t, cost = price, key = "u" .. t, pay = { kind = "Unlock", tool = t }, stand = F.STAND[t] and t, block = true } end
    end
    if canBag and M.n("BagLevel") >= 5 then
        steps[#steps + 1] = { label = "Bag level " .. (M.n("BagLevel") + 1), cost = bagC, key = "bag", pay = { kind = "Bag" } }
    end
    if on("u_stats") then
        local t = M.a("Equipped") or "Hands"
        local ss = val("u_statlist", nil)
        for _, st in ipairs(F.STATS[t] or {}) do
            if (type(ss) ~= "table" or ss[st] == true) and (F.statMax[t .. st] or 0) < os.clock() then
                steps[#steps + 1] = { label = t .. " " .. st, cost = nil, key = "s" .. t .. st, pay = { kind = "Upgrade", tool = t, stat = st }, stat = t .. st }
            end
        end
    end
    return steps
end
function F.shop()
    local keep = tonumber(val("u_keep", "0")) or 0
    local spend = M.n("Cash") - keep
    local steps = F.plan()
    F.nextBuy = nil
    for _, s in ipairs(steps) do
        local affordable = s.cost == nil or spend >= s.cost
        if not affordable and s.skipIfPoor then
        elseif not affordable then
            F.nextBuy = string.format(__T["%s ($%s) · saving"], s.label, M.fmt(s.cost))
            if s.block then return end
        else
            F.nextBuy = s.label .. (s.cost and (" ($" .. M.fmt(s.cost) .. ")") or "")
            local ok
            if s.stand then ok = F.standBuy(s.stand) else ok = F.tryBuy(s.key, s.pay) end
            if ok then return end
            if s.bin and (os.clock() - (F.lastBuy[s.key] or 0)) < 1 then F.binLocked[s.bin] = os.clock() + 30 end
            if s.stat and (os.clock() - (F.lastBuy[s.key] or 0)) < 1 then F.statMax[s.stat] = os.clock() + 60 end
            if s.block then return end
        end
    end
    if not F.nextBuy then F.nextBuy = __T["Nothing left to buy"] end
    F.saving = nil
    for _, s in ipairs(steps) do if s.block and s.cost and spend < s.cost then F.saving = s.label end end
end
function F.equip()
