local L = { lastStart = 0, lastClaim = 0, lastUp = 0, lastHatch = 0 }
L.OURS = { "StartCash", "CashBoost", "StartBag", "QuickDump", "GemBoost", "WalkSpeed" }
function L.upgList()
    local out = {}
    pcall(function() for _, u in ipairs(D.Upg.List) do if type(u) == "table" and u.Id then out[#out + 1] = u.Id end end end)
    if #out == 0 then out = { "StartCash", "CashBoost", "StartBag", "QuickDump", "GemBoost", "WalkSpeed", "RareRadar", "BugSense", "PetSlot2", "PetSlot3" } end
    local set = {}
    for _, id in ipairs(out) do set[id] = true end
    local ordered = {}
    for _, id in ipairs(L.OURS) do if set[id] then ordered[#ordered + 1] = id set[id] = nil end end
    for _, id in ipairs(out) do if set[id] then ordered[#ordered + 1] = id end end
    L._upgs = ordered
    return ordered
end
function L.upgDefault()
    local list = L._upgs or L.upgList()
    local set, out = {}, {}
    for _, id in ipairs(list) do set[id] = true end
    for _, id in ipairs(L.OURS) do if set[id] then out[#out + 1] = id end end
    return out
end
function L.houseOrder()
    local order = {}
    pcall(function() for _, id in ipairs(D.Lobby.HouseOrder) do order[#order + 1] = id end end)
    if #order == 0 then order = { "House", "NextDoor", "Camp" } end
    return order
