function L.freeBoard()
    local lobby = Workspace:FindFirstChild("Lobby")
    local play = lobby and lobby:FindFirstChild("Play")
    local fallback
    for i = 1, 4 do
        local b = play and play:FindFirstChild("Board" .. i)
        local p = b and b:FindFirstChild("Pad", true)
        if p then
            local busy = false
            for _, pl in ipairs(Players:GetPlayers()) do
                if pl ~= lp and pl.Character and pl.Character:FindFirstChild("HumanoidRootPart") then
                    local d = pl.Character.HumanoidRootPart.Position - p.Position
                    if Vector3.new(d.X, 0, d.Z).Magnitude < 7 then busy = true end
                end
            end
            if not busy then return i, p end
            fallback = fallback or { i, p }
        end
    end
    if fallback then return fallback[1], fallback[2] end
end
function L.start()
    if os.clock() - L.lastStart < 20 then return end
    L.lastStart = os.clock()
    local board, pad = L.freeBoard()
    if not pad then return end
    S.task = __T["Starting a house"]
    M.tp(pad.Position + Vector3.new(0, 3, 0))
    task.wait(1.2)
    M.invoke("JoinGame", board)
    task.wait(0.4)
    local pick = val("l_map", "Best Unlocked")
    local maps = { pick }
    if pick == "Best Unlocked" then
        maps = {}
        local order = L.houseOrder()
        for i = #order, 1, -1 do maps[#maps + 1] = order[i] end
    end
    local ok = false
    for _, map in ipairs(maps) do
        local set = { maxPlayers = 1, difficulty = val("l_diff", "Easy"), friendsOnly = false, house = map, pro = false }
        for _, mode in ipairs({ "continue", "new", false }) do
            set.mode = mode or nil
            if M.ok(M.invoke("CreateGame", board, set)) then ok = true break end
            task.wait(0.25)
        end
        if ok then S.map = map break end
    end
    task.wait(0.4)
    local r = M.invoke("StartNow", board)
    if not (ok or M.ok(r)) then
        F.note = __T["Couldn't start, retrying"]
        M.fire("LeavePad", "button")
    else
        F.note = ""
    end
end
