    if not (D.Net and D.CTB) then
        lines[#lines + 1] = '<font color="#ff6b6b">' .. __T["Your executor can't read game data. Some features are off."] .. '</font>'
    end
    if #lines > 0 then
        setText(UI.exec, table.concat(lines, "\n"))
    else
        setText(UI.exec, '<font color="#7ED957">' .. __T["Executor check: all features supported"] .. '</font>')
    end
end)
